/**
 * Audit Log JS - Audit log page functionality
 */

const state = {
    currentPage: 1,
    pageSize: 20,
    totalPages: 1,
    isLoading: false
};

const elements = {
    table: null,
    tableBody: null,
    pagination: null
};

/**
 * Initialize audit log page
 */
function initAuditLogPage() {
    elements.table = document.getElementById('audit-log-table');
    elements.tableBody = document.querySelector('#audit-log-table tbody');
    elements.pagination = document.querySelector('.pagination');

    const authToken = localStorage.getItem('authToken');
    if (!authToken) {
        window.location.href = 'login.html';
        return;
    }

    loadAuditLog(state.currentPage, state.pageSize);
}

/**
 * Load audit log entries
 * @param {number} page - Page number for pagination
 * @param {number} pageSize - Number of entries per page
 */
async function loadAuditLog(page = 1, pageSize = 20) {
    // TODO: Fetch audit log data from API
    try {
        state.isLoading = true;

        const response = await fetch('http://127.0.0.1:8080/api/audit-log?page=' + page + '&pageSize=' + pageSize, {
            headers: {
                'Authorization': 'Bearer ' + authToken
            }
        });
        const data = await response.json();
        renderAuditLogTable(data.entries);
        renderPagination(data.currentPage, data.totalPages);
    } catch (error) {
        console.error('Error loading audit log:', error);
    } finally {
        state.isLoading = false;
    }
}

/**
 * Render audit log table
 * @param {Array} entries - Audit log entries
 */
function renderAuditLogTable(entries) {
    if (!elements.tableBody) {
        return;
    }

    elements.tableBody.innerHTML = '';

    if (!Array.isArray(entries) || entries.length === 0) {
        const emptyRow = document.createElement('tr');
        const emptyCell = document.createElement('td');
        emptyCell.colSpan = 4;
        emptyCell.textContent = 'No audit log entries found.';
        emptyRow.appendChild(emptyCell);
        elements.tableBody.appendChild(emptyRow);
        return;
    }

    entries.forEach((entry) => {
        const row = document.createElement('tr');

        const timestampCell = document.createElement('td');
        timestampCell.className = 'timestamp-cell';
        timestampCell.textContent = formatTimestamp(entry.timestamp);

        const actionCell = document.createElement('td');
        actionCell.innerHTML = formatActionType(entry.action);

        const descriptionCell = document.createElement('td');
        descriptionCell.textContent = entry.description || '';

        const detailsCell = document.createElement('td');
        detailsCell.className = 'details-cell';
        detailsCell.textContent = entry.details || '';

        row.appendChild(timestampCell);
        row.appendChild(actionCell);
        row.appendChild(descriptionCell);
        row.appendChild(detailsCell);

        elements.tableBody.appendChild(row);
    });

}

/**
 * Format action type for display
 * @param {string} action - Action type
 * @returns {string} - Formatted action with badge class
 */
function formatActionType(action) {
    // TODO: Return formatted action badge HTML
}

